nodes.text_raw:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg: #0a0b0e;
  --card: #15171c;
  --card-2: #1a1d24;
  --border: rgba(255, 255, 255, 0.07);
  --fg: #f0eee8;
  --muted: #9a9aa3;
  --dim: #5a5a64;
  --accent: #f5a623;
  --accent-glow: rgba(245, 166, 35, 0.20);
  --cool: #6ba6e8;
}

html, body {
  width: 100%;
  height: 100%;
  background: var(--bg);
  color: var(--fg);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(ellipse 900px 700px at 18% 22%, rgba(245, 166, 35, 0.05), transparent 65%),
    radial-gradient(ellipse 700px 900px at 82% 78%, rgba(107, 166, 232, 0.04), transparent 65%),
    var(--bg);
}

.card {
  width: 1120px;
  height: 720px;
  background: linear-gradient(180deg, var(--card) 0%, var(--card-2) 100%);
  border: 1px solid var(--border);
  border-radius: 28px;
  padding: 52px 64px;
  display: grid;
  grid-template-rows: auto 1fr auto;
  gap: 28px;
  position: relative;
  overflow: hidden;
  box-shadow:
    0 50px 100px rgba(0, 0, 0, 0.55),
    0 0 0 1px rgba(255, 255, 255, 0.02),
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.card::before {
  content: '';
  position: absolute;
  top: -260px;
  right: -220px;
  width: 620px;
  height: 620px;
  border-radius: 50%;
  background: radial-gradient(circle, var(--accent-glow), transparent 70%);
  pointer-events: none;
  transition: background 0.8s ease;
  animation: glowPulse 9s ease-in-out infinite;
}

.card::after {
  content: '';
  position: absolute;
  bottom: -220px;
  left: -180px;
  width: 460px;
  height: 460px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(107, 166, 232, 0.07), transparent 70%);
  pointer-events: none;
}

@keyframes glowPulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.75; transform: scale(1.06); }
}

/* Header */
.header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  position: relative;
  z-index: 2;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--border);
}

.label {
  font-size: 10px;
  letter-spacing: 0.32em;
  color: var(--dim);
  text-transform: uppercase;
  margin-bottom: 12px;
  font-weight: 500;
}

.location-block .name {
  font-size: 52px;
  font-weight: 200;
  letter-spacing: -0.02em;
  line-height: 1;
  color: var(--fg);
}

.date-block { text-align: right; }

.date-block .date {
  font-size: 22px;
  font-weight: 300;
  color: var(--muted);
  letter-spacing: 0.02em;
}

/* Hero */
.hero {
  display: flex;
  align-items: center;
  gap: 48px;
  position: relative;
  z-index: 2;
}

.weather-icon {
  width: 132px;
  height: 132px;
  flex-shrink: 0;
  color: var(--accent);
  animation: iconFloat 7s ease-in-out infinite;
  transition: color 0.6s ease;
}

.weather-icon svg {
  width: 100%;
  height: 100%;
  filter: drop-shadow(0 0 28px var(--accent-glow));
}

@keyframes iconFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-7px); }
}

.hero-text { flex: 1; }

.condition {
  font-size: 26px;
  font-weight: 300;
  color: var(--fg);
  margin-bottom: 6px;
  letter-spacing: -0.01em;
}

.condition-meta {
  font-size: 12px;
  color: var(--muted);
  letter-spacing: 0.04em;
  margin-bottom: 22px;
}

.temp-display {
  display: flex;
  align-items: baseline;
  gap: 40px;
}

.temp-high {
  font-size: 88px;
  font-weight: 100;
  line-height: 0.9;
  letter-spacing: -0.045em;
  color: var(--fg);
}

.temp-high .unit {
  font-size: 30px;
  vertical-align: super;
  color: var(--muted);
  margin-left: 6px;
  font-weight: 300;
}

.temp-low {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-left: 28px;
  border-left: 1px solid var(--border);
}

.temp-low .low-label {
  font-size: 10px;
  letter-spacing: 0.32em;
  color: var(--dim);
  text-transform: uppercase;
  font-weight: 500;
}

.temp-low .low-value {
  font-size: 32px;
  font-weight: 300;
  color: var(--cool);
  letter-spacing: -0.02em;
}

/* Chart */
.chart-section {
  position: relative;
  z-index: 2;
}

.chart-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 14px;
}

.chart-title {
  font-size: 10px;
  letter-spacing: 0.32em;
  color: var(--dim);
  text-transform: uppercase;
  font-weight: 500;
}

.chart-stats {
  display: flex;
  gap: 28px;
  font-size: 12px;
  color: var(--muted);
}

.chart-stats strong {
  color: var(--fg);
  font-weight: 400;
  margin-left: 6px;
}

.chart-container {
  height: 188px;
  position: relative;
}

.chart-container svg {
  width: 100%;
  height: 100%;
  overflow: visible;
  display: block;
}

.tooltip {
  position: absolute;
  pointer-events: none;
  background: rgba(15, 16, 20, 0.92);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 8px 12px;
  font-size: 12px;
  color: var(--fg);
  transform: translate(-50%, -130%);
  transition: opacity 0.15s;
  white-space: nowrap;
  -webkit-backdrop-filter: blur(10px);
  backdrop-filter: blur(10px);
  z-index: 10;
}

.tooltip .t-time {
  color: var(--muted);
  font-size: 10px;
  letter-spacing: 0.18em;
  margin-bottom: 3px;
  text-transform: uppercase;
}

.tooltip .t-temp {
  font-size: 15px;
  font-weight: 400;
}

/* States */
.hidden { display: none !important; }

.state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  text-align: center;
  gap: 22px;
  padding: 40px;
  position: relative;
  z-index: 2;
}

.state-icon {
  width: 60px;
  height: 60px;
  color: var(--accent);
  opacity: 0.75;
}

.state-title {
  font-size: 24px;
  font-weight: 300;
  letter-spacing: -0.01em;
}

.state-message {
  font-size: 13px;
  color: var(--muted);
  max-width: 400px;
  line-height: 1.6;
}

.loading-dots { display: flex; gap: 8px; }

.loading-dots span {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
  animation: dotPulse 1.4s infinite ease-in-out;
}

.loading-dots span:nth-child(2) { animation-delay: 0.18s; }
.loading-dots span:nth-child(3) { animation-delay: 0.36s; }

@keyframes dotPulse {
  0%, 80%, 100% { opacity: 0.2; transform: scale(0.7); }
  40% { opacity: 1; transform: scale(1.1); }
}

/* Entrance */
.fade-in { animation: fadeIn 0.7s ease-out both; }

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.delay-1 { animation-delay: 0.08s; }
.delay-2 { animation-delay: 0.16s; }
.delay-3 { animation-delay: 0.24s; }

