  function buildChart(times, temps, maxT, minT) {
    const svg = document.getElementById('chart');
    const container = svg.parentElement;
    const W = container.clientWidth;
    const H = container.clientHeight;
    if (W < 10 || H < 10) return;

    const padL = 38, padR = 18, padT = 18, padB = 30;
    const innerW = Math.max(W - padL - padR, 1);
    const innerH = Math.max(H - padT - padB, 1);

    svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
    svg.innerHTML = '';

    const accent = getComputedStyle(document.documentElement).getPropertyValue('--accent').trim() || '#f5a623';
    const cardBg = '#1a1d24';

    const range = Math.max(maxT - minT, 1);
    const pad = range * 0.22;
    const yMin = minT - pad;
    const yMax = maxT + pad;
    const yRange = Math.max(yMax - yMin, 1);

    const n = temps.length;
    const xFor = i => padL + (n > 1 ? (i / (n - 1)) * innerW : innerW / 2);
    const yFor = t => padT + (1 - (t - yMin) / yRange) * innerH;
    const points = temps.map((t, i) => ({ x: xFor(i), y: yFor(t) }));

    const ns = 'http://www.w3.org/2000/svg';

    // Grid lines
    const gridCount = 4;
    for (let i = 0; i <= gridCount; i++) {
      const y = padT + (i / gridCount) * innerH;
      const val = yMax - (i / gridCount) * yRange;
      const line = document.createElementNS(ns, 'line');
      line.setAttribute('x1', padL);
      line.setAttribute('y1', y);
      line.setAttribute('x2', W - padR);
      line.setAttribute('y2', y);
      line.setAttribute('stroke', 'rgba(255,255,255,0.06)');
      line.setAttribute('stroke-width', '1');
      if (i > 0 && i < gridCount) line.setAttribute('stroke-dasharray', '2,4');
      svg.appendChild(line);

      const label = document.createElementNS(ns, 'text');
      label.setAttribute('x', padL - 10);
      label.setAttribute('y', y + 4);
      label.setAttribute('text-anchor', 'end');
      label.setAttribute('fill', 'rgba(255,255,255,0.35)');
      label.setAttribute('font-size', '10');
      label.setAttribute('font-family', 'inherit');
      label.textContent = Math.round(val) + '°';
      svg.appendChild(label);
    }

    // Build smooth path
    let pathD = '';
    let areaD = '';
    points.forEach((p, i) => {
      if (i === 0) {
        pathD += `M ${p.x.toFixed(2)} ${p.y.toFixed(2)}`;
        areaD += `M ${p.x.toFixed(2)} ${p.y.toFixed(2)}`;
      } else {
        const prev = points[i - 1];
        const cpX = (prev.x + p.x) / 2;
        pathD += ` C ${cpX.toFixed(2)} ${prev.y.toFixed(2)}, ${cpX.toFixed(2)} ${p.y.toFixed(2)}, ${p.x.toFixed(2)} ${p.y.toFixed(2)}`;
        areaD += ` C ${cpX.toFixed(2)} ${prev.y.toFixed(2)}, ${cpX.toFixed(2)} ${p.y.toFixed(2)}, ${p.x.toFixed(2)} ${p.y.toFixed(2)}`;
      }
    });
    const lastP = points[n - 1];
    const firstP = points[0];
    areaD += ` L ${lastP.x.toFixed(2)} ${(padT + innerH).toFixed(2)} L ${firstP.x.toFixed(2)} ${(padT + innerH).toFixed(2)} Z`;

    // Defs / gradient
    const defs = document.createElementNS(ns, 'defs');
    const grad = document.createElementNS(ns, 'linearGradient');
    grad.setAttribute('id', 'area-grad');
    grad.setAttribute('x1', '0'); grad.setAttribute('y1', '0');
    grad.setAttribute('x2', '0'); grad.setAttribute('y2', '1');
    const s1 = document.createElementNS(ns, 'stop');
    s1.setAttribute('offset', '0%');
    s1.setAttribute('stop-color', accent);
    s1.setAttribute('stop-opacity', '0.35');
    const s2 = document.createElementNS(ns, 'stop');
    s2.setAttribute('offset', '100%');
    s2.setAttribute('stop-color', accent);
    s2.setAttribute('stop-opacity', '0');
    grad.appendChild(s1); grad.appendChild(s2);
    defs.appendChild(grad);
    svg.appendChild(defs);

    // Area
    const area = document.createElementNS(ns, 'path');
    area.setAttribute('d', areaD);
    area.setAttribute('fill', 'url(#area-grad)');
    area.style.opacity = '0';
    area.style.transition = 'opacity 1s ease 0.4s';
    svg.appendChild(area);
    requestAnimationFrame(() => { area.style.opacity = '1'; });

    // Line
    const line = document.createElementNS(ns, 'path');
    line.setAttribute('d', pathD);
    line.setAttribute('fill', 'none');
    line.setAttribute('stroke', accent);
    line.setAttribute('stroke-width', '2.2');
    line.setAttribute('stroke-linecap', 'round');
    line.setAttribute('stroke-linejoin', 'round');
    svg.appendChild(line);

    // Draw-in animation
    try {
      const pathLen = line.getTotalLength();
      line.style.strokeDasharray = pathLen;
      line.style.strokeDashoffset = pathLen;
      line.style.transition = 'stroke-dashoffset 1.4s cubic-bezier(0.22, 0.61, 0.36, 1) 0.3s';
      requestAnimationFrame(() => { line.style.strokeDashoffset = '0'; });
    } catch(e) { /* getTotalLength may fail in some browsers; ignore */ }

    // X-axis labels
    const labelStep = Math.max(1, Math.floor(n / 8));
    for (let i = 0; i < n; i += labelStep) {
      const x = xFor(i);
      const label = document.createElementNS(ns, 'text');
      label.setAttribute('x', x);
      label.setAttribute('y', H - padB + 18);
      label.setAttribute('text-anchor', 'middle');
      label.setAttribute('fill', 'rgba(255,255,255,0.42)');
      label.setAttribute('font-size', '10');
      label.setAttribute('font-family', 'inherit');
      label.textContent = formatHour(times[i]);
      svg.appendChild(label);
    }

    // Min/max markers
    const maxIdx = temps.indexOf(maxT);
    const minIdx = temps.indexOf(minT);
    [maxIdx, minIdx].forEach(idx => {
      const p = points[idx];
      const outer = document.createElementNS(ns, 'circle');
      outer.setAttribute('cx', p.x);
      outer.setAttribute('cy', p.y);
      outer.setAttribute('r', '7');
      outer.setAttribute('fill', accent);
      outer.setAttribute('fill-opacity', '0.18');
      svg.appendChild(outer);

      const c = document.createElementNS(ns, 'circle');
      c.setAttribute('cx', p.x);
      c.setAttribute('cy', p.y);
      c.setAttribute('r', '3.5');
      c.setAttribute('fill', cardBg);
      c.setAttribute('stroke', accent);
      c.setAttribute('stroke-width', '2');
      svg.appendChild(c);
    });

    // Hover elements
    const tooltip = document.getElementById('tooltip');
    const hoverDot = document.createElementNS(ns, 'circle');
    hoverDot.setAttribute('r', '5');
    hoverDot.setAttribute('fill', '#ffffff');
    hoverDot.setAttribute('stroke', accent);
    hoverDot.setAttribute('stroke-width', '2.5');
    hoverDot.style.opacity = '0';
    hoverDot.style.transition = 'opacity 0.15s';
    svg.appendChild(hoverDot);

    const hoverLine = document.createElementNS(ns, 'line');
    hoverLine.setAttribute('y1', padT);
    hoverLine.setAttribute('y2', padT + innerH);
    hoverLine.setAttribute('stroke', 'rgba(255,255,255,0.18)');
    hoverLine.setAttribute('stroke-width', '1');
    hoverLine.setAttribute('stroke-dasharray', '2,3');
    hoverLine.style.opacity = '0';
    hoverLine.style.transition = 'opacity 0.15s';
    svg.appendChild(hoverLine);

    const overlay = document.createElementNS(ns, 'rect');
    overlay.setAttribute('x', padL);
    overlay.setAttribute('y', padT);
    overlay.setAttribute('width', innerW);
    overlay.setAttribute('height', innerH);
    overlay.setAttribute('fill', 'transparent');
    overlay.style.cursor = 'crosshair';
    svg.appendChild(overlay);

    overlay.addEventListener('mousemove', (e) => {
      const rect = svg.getBoundingClientRect();
      const scaleX = W / rect.width;
      const mouseX = (e.clientX - rect.left) * scaleX;
      const relX = (mouseX - padL) / innerW;
      const idx = Math.max(0, Math.min(n - 1, Math.round(relX * (n - 1))));
      const p = points[idx];
      hoverDot.setAttribute('cx', p.x);
      hoverDot.setAttribute('cy', p.y);
      hoverDot.style.opacity = '1';
      hoverLine.setAttribute('x1', p.x);
      hoverLine.setAttribute('x2', p.x);
      hoverLine.style.opacity = '1';

      const pixelX = (p.x / W) * rect.width;
      const pixelY = (p.y / H) * rect.height;
      tooltip.style.left = pixelX + 'px';
      tooltip.style.top = pixelY + 'px';
      tooltip.classList.remove('hidden');
      tooltip.querySelector('.t-time').textContent = formatHour(times[idx]) + ' UTC';
      tooltip.querySelector('.t-temp').textContent = temps[idx].toFixed(1) + '°C';
    });

    overlay.addEventListener('mouseleave', () => {
      hoverDot.style.opacity = '0';
      hoverLine.style.opacity = '0';
      tooltip.classList.add('hidden');
    });
  }

  // ---------- Main ----------
  async function init() {
    document.getElementById('loc-name').textContent = name;
    document.getElementById('loc-date').textContent = formatDate(requestedDate);

    const query = new URLSearchParams({
      latitude: String(lat),
      longitude: String(lon),
      daily: 'temperature_2m_max,temperature_2m_min,weather_code',
      hourly: 'temperature_2m',
      timezone: 'UTC',
      temperature_unit: 'celsius',
      start_date: requestedDate,
      end_date: requestedDate
    });
    const url = `${endpoint}?${query.toString()}`;

    try {
      const res = await fetch(url);
      if (!res.ok) throw new Error(`Server responded with status ${res.status}`);
      const data = await res.json();

      if (!data || !data.daily || !data.daily.time || !data.daily.time.length ||
          !data.hourly || !Array.isArray(data.hourly.temperature_2m) || !data.hourly.temperature_2m.length) {
        throw new Error('No weather data available for this date.');
      }

      const maxT = data.daily.temperature_2m_max[0];
      const minT = data.daily.temperature_2m_min[0];
      const code = data.daily.weather_code[0];
      const wc = weatherCodes[code] || {
        desc: 'Weather condition ' + code,
        icon: 'cloud',
        accent: '#a8b3c1',
        glow: 'rgba(168,179,193,0.12)'
      };

      setAccent(wc.accent, wc.glow);

      document.getElementById('temp-high').textContent = Math.round(maxT);
      document.getElementById('temp-low').textContent = Math.round(minT) + '°';
      document.getElementById('condition').textContent = wc.desc;
      document.getElementById('weather-icon').innerHTML = icons[wc.icon] || icons.cloud;

      const times = data.hourly.time;
      const temps = data.hourly.temperature_2m;

      let maxHr = 0, minHr = 0;
      for (let i = 1; i < temps.length; i++) {
        if (temps[i] > temps[maxHr]) maxHr = i;
        if (temps[i] < temps[minHr]) minHr = i;
      }
      document.getElementById('condition-meta').textContent =
        `Peak at ${formatHour(times[maxHr])}  ·  Lowest at ${formatHour(times[minHr])}  ·  ${temps.length} hourly readings`;

      const avg = temps.reduce((a, b) => a + b, 0) / temps.length;
      document.getElementById('chart-stats').innerHTML =
        `<span>Average<strong>${avg.toFixed(1)}°C</strong></span>` +
        `<span>Range<strong>${(maxT - minT).toFixed(1)}°C</strong></span>`;

      showContent();
      chartCache = { times, temps, maxT, minT };
      requestAnimationFrame(() => buildChart(times, temps, maxT, minT));
    } catch (err) {
      console.error('Weather fetch error:', err);
      showError(err.message || 'Could not retrieve weather data. Please try again.');
    }
  }

  // Rebuild chart on resize (debounced)
  let resizeTimer;
  window.addEventListener('resize', () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
      if (chartCache) buildChart(chartCache.times, chartCache.temps, chartCache.maxT, chartCache.minT);
    }, 150);
  });

  init();
})();
